import{_ as t,o as r,c as e,a2 as l}from"./chunks/framework.wVcpyw2-.js";const c=JSON.parse('{"title":"抽奖活动","description":"抽奖活动：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/lottery.md","filePath":"features/lottery.md","lastUpdated":1785020677000}'),o={name:"features/lottery.md"};function i(n,a,s,h,u,d){return r(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="抽奖活动" tabindex="-1">抽奖活动 <a class="header-anchor" href="#抽奖活动" aria-label="Permalink to &quot;抽奖活动&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>创建与管理平台抽奖活动，配置奖品、开奖规则，并审核中奖记录。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>抽奖模块已在授权中开通。</li><li>若活动需付费参与或奖品涉及余额 / 支付，须配置 <a href="/features/payment">支付与提现</a>。</li><li>具备 <strong>平台推广 → 抽奖管理</strong> 访问权限。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><p>路径：<strong>平台推广 → 抽奖管理</strong></p><p>典型操作流程：</p><ol><li><strong>新建活动</strong> — 填写名称、时间、参与条件、奖品设置</li><li><strong>发布</strong> — 使活动在客户端可见（以页面状态流转为准）</li><li><strong>监控参与</strong> — 列表查看参与人数、奖池消耗</li><li><strong>中奖处理</strong> — 审核或确认中奖用户，安排发奖</li><li><strong>结束 / 下架</strong> — 到期后关闭入口</li></ol><p>奖品类型可能包括：积分、余额、实物、优惠券等，以创建表单选项为准。</p><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>抽奖活动创建时可绑定 <strong>适用区域</strong> 或全站（以创建页字段为准）。仅绑定区域的用户可见并参与。</p><p>区域级推广、补贴规则与 <a href="/features/coupon">优惠券与营销</a> 独立；抽奖一般不参与推广员分佣（除非业务另行配置）。</p><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>创建测试抽奖，时间设为当前有效，奖品为少量积分。</li><li>客户端在对应区域看到活动入口，成功参与一次。</li><li><strong>抽奖管理</strong> 列表参与数增加；若即时开奖，中奖记录出现且用户积分 / 余额变动可在 <strong>积分流水 / 余额流水</strong> 中核对。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>客户端没有抽奖入口</strong></p><ul><li>活动未发布或已过期。</li><li>用户所在区域不在活动范围。</li><li><strong>UI管理</strong> 未配置展示入口。</li></ul><p><strong>开奖异常或重复中奖</strong></p><ul><li>检查活动规则中的每人限次、总名额。</li><li>在列表中找到活动查看异常状态，必要时手动下架。</li></ul><p><strong>实物奖品如何发放</strong></p><ul><li>在 <strong>抽奖管理</strong> 中记录中奖用户信息，线下发货后在后台标记完成（以页面操作为准）。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/coupon">优惠券与营销</a></li><li><a href="/features/promotion">推广员体系</a></li><li><a href="/features/finance">财务流水与提现</a></li><li><a href="/features/payment">支付与提现</a></li></ul>',24)])])}const f=t(o,[["render",i]]);export{c as __pageData,f as default};
